import {form,number as num,select as sel,text,area,result,outputText,e,n,download,copyText,notify} from './ui.mjs';
import {icon} from './catalog.mjs';
import {subtitleConvert,jsonCSV,campaignURL,contrastRatio} from './extra-core.mjs';
const need=(ok,message)=>{if(!ok)throw Error(message);};
const scriptPromises=new Map();
export function loadScript(path,globalName){if(window[globalName])return Promise.resolve(window[globalName]);if(!scriptPromises.has(path))scriptPromises.set(path,new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL(path,document.baseURI).href;s.onload=()=>resolve(window[globalName]);s.onerror=()=>{scriptPromises.delete(path);reject(Error('Could not load this tool. Check your connection and try again.'));};document.head.append(s);}));return scriptPromises.get(path);}
const sampleSubtitle='1\n00:00:01,000 --> 00:00:03,500\nA little idea can go a long way.\n\n2\n00:00:04,000 --> 00:00:06,000\nMake something worth sharing.';
export function setupExtra(tool,mount,out){
 const show=o=>result(out,o),id=tool.id;
 if(id==='subtitle-converter')form(mount,[area('input','SRT or WebVTT text',sampleSubtitle),sel('target','Output format',[['vtt','WebVTT (.vtt)'],['srt','SubRip (.srt)']],'vtt')],v=>{const r=subtitleConvert(v.input,v.target);outputText(out,r.text,[['Subtitle cues',r.count],['Output',v.target.toUpperCase()]]);const b=document.createElement('button');b.className='btn primary small';b.textContent='Download subtitles';b.onclick=()=>download(new Blob([r.text],{type:'text/plain;charset=utf-8'}),'nepocore-subtitles.'+v.target);out.querySelector('.result-actions').append(b);},{label:'Convert subtitles',note:'Converts text subtitle files; it does not transcribe audio or burn captions into video. SRT output drops VTT positioning and style blocks.'});
 else if(id==='utm-builder')form(mount,[text('url','Destination URL','https://nepocore.com','url',true),text('source','Campaign source','instagram'),text('medium','Campaign medium','social'),text('campaign','Campaign name','creator-launch'),{...text('content','Content label (optional)','bio-link'),required:false},{...text('term','Search term (optional)',''),required:false}],v=>{const u=campaignURL(v.url,v);outputText(out,u,[['Destination host',new URL(u).hostname],['Tracking','UTM parameters only; no redirect service']]);},{label:'Build campaign link',note:'UTM tags label incoming traffic for your own analytics. This tool does not track, shorten, or send the link.'});
 else if(id==='gradient-generator'){
  const f=form(mount,[text('a','First color','#d7edcc','color'),text('b','Second color','#6477b3','color'),text('c','Third color','#f6d7bf','color'),num('angle','Angle (degrees)',130,0,360,1),sel('type','Gradient type',[['linear','Linear'],['radial','Radial']],'linear')],v=>{const css=v.type==='linear'?`linear-gradient(${v.angle}deg, ${v.a}, ${v.b}, ${v.c})`:`radial-gradient(circle at 30% 30%, ${v.a}, ${v.b}, ${v.c})`;show({html:`<div class="design-preview gradient-preview" style="background:${css}" aria-label="Generated gradient"></div><pre class="result-output">${e('background: '+css+';')}</pre>`,copy:'background: '+css+';'});},{label:'Create gradient'});f.addEventListener('input',()=>f.requestSubmit());
 }else if(id==='glassmorphism'){
  const f=form(mount,[num('blur','Blur (px)',16,0,40,1),num('opacity','White opacity (%)',18,0,100,1),num('radius','Corner radius (px)',24,0,60,1),text('a','Background start','#548d79','color'),text('b','Background end','#677cba','color')],v=>{const css=`background: rgba(255, 255, 255, ${+v.opacity/100});\nbackdrop-filter: blur(${v.blur}px);\n-webkit-backdrop-filter: blur(${v.blur}px);\nborder: 1px solid rgba(255, 255, 255, 0.3);\nborder-radius: ${v.radius}px;\nbox-shadow: 0 12px 40px rgba(0, 0, 0, 0.12);`;show({html:`<div class="design-preview glass-preview" style="background:linear-gradient(135deg,${v.a},${v.b})"><i class="glass-orb"></i><div style="${css}"><span>A LITTLE CLARITY</span><strong>Make space<br>for possibility.</strong><small>Your next beautiful interface.</small></div></div><pre class="result-output">${e(css)}</pre>`,copy:css,note:'Place the card over an image or colored background to see the glass effect. Backdrop-filter support depends on the browser.'});},{label:'Generate glass effect'});f.addEventListener('input',()=>f.requestSubmit());
 }else if(id==='contrast-checker'){
  const f=form(mount,[text('foreground','Text color','#173d36','color'),text('background','Background color','#f8f9f6','color')],v=>{const r=contrastRatio(v.foreground,v.background);show({label:'Contrast ratio',value:r.toFixed(2)+':1',html:`<div class="contrast-preview" style="color:${v.foreground};background:${v.background}"><strong>A little clarity.</strong><p>Readable design starts with the details.</p></div>`,details:[['AA — normal text',r>=4.5?'Pass (≥ 4.5:1)':'Does not pass'],['AA — large text',r>=3?'Pass (≥ 3:1)':'Does not pass'],['AAA — normal text',r>=7?'Pass (≥ 7:1)':'Does not pass'],['AAA — large text',r>=4.5?'Pass (≥ 4.5:1)':'Does not pass']],copy:r.toFixed(2)+':1',note:'WCAG contrast thresholds. Large text means at least 18 pt regular or 14 pt bold. This checks opaque solid colors, not a full accessibility audit.'});},{label:'Check contrast',note:'Based on <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener">WCAG contrast guidance ↗</a>.'});f.addEventListener('input',()=>f.requestSubmit());
 }else if(id==='markdown-to-html')form(mount,[area('markdown','Your Markdown','# A little idea\n\nMake something **useful** and share it.\n\n- Clear purpose\n- Thoughtful details\n- A little personality\n\n[Explore Nepocore](https://nepocore.com)')],async v=>{const {marked}=await import('./assets/vendor/marked.esm.js'),purify=await loadScript('./assets/vendor/purify.min.js','DOMPurify');const html=purify.sanitize(marked.parse(v.markdown),{USE_PROFILES:{html:true},FORBID_TAGS:['style','iframe','form','input','button','video','audio','img'],FORBID_ATTR:['style','id','name']});show({html:`<div class="markdown-preview">${html}</div><h3 class="output-caption">Sanitized HTML</h3><pre class="result-output">${e(html)}</pre>`,copy:html,note:'Markdown is rendered locally. Embedded media, scripts, styles and form controls are removed from the preview.'});out.querySelectorAll('.markdown-preview a').forEach(a=>{a.target='_blank';a.rel='noopener noreferrer';});const b=document.createElement('button');b.className='btn primary small';b.textContent='Download HTML';b.onclick=()=>download(new Blob(['<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Markdown document</title><main>'+html+'</main>'],{type:'text/html;charset=utf-8'}),'nepocore-document.html');out.querySelector('.result-actions').append(b);},{label:'Render Markdown'});
 else if(id==='json-to-csv')form(mount,[area('json','JSON array of objects','[\n  {"name":"Nabi","role":"Developer","country":"Nepal"},\n  {"name":"Aarya","role":"Designer","country":"Nepal"}\n]'),sel('delimiter','Column separator',[[',','Comma'],[';','Semicolon'],['\t','Tab']],','),sel('safe','Spreadsheet formula handling',[['yes','Neutralize text starting with formula characters'],['no','Keep raw text values']],'yes')],v=>{const r=jsonCSV(v.json,v.delimiter,v.safe==='yes');outputText(out,r.text.replace(/^\uFEFF/,''),[['Rows',r.rows],['Columns',r.columns.length]]);const b=document.createElement('button');b.className='btn primary small';b.textContent='Download CSV';b.onclick=()=>download(new Blob([r.text],{type:'text/csv;charset=utf-8'}),'nepocore-data.csv');out.querySelector('.result-actions').append(b);},{label:'Convert JSON to CSV',note:'Uses the union of object keys as column names. Nested objects are preserved as JSON text. UTF-8 export includes a BOM for spreadsheet compatibility.'});
 else if(id==='emoji-picker'){
  const emojis=[['😀','happy smile'],['😄','laugh joy'],['😂','laugh tears funny'],['🥹','happy tears grateful'],['😍','love heart eyes'],['🥰','love smile'],['😎','cool sunglasses'],['🤔','thinking question'],['🫡','salute respect'],['🤗','hug welcome'],['😭','cry sad'],['😴','sleep tired'],['🤯','mind blown'],['🥳','party birthday'],['😅','nervous sweat'],['🤩','star excited'],['🙂','smile'],['🙃','upside down'],['🫠','melting'],['🤝','handshake deal'],['👍','thumbs up yes'],['👎','thumbs down no'],['🙌','celebrate hands'],['👏','clap applause'],['🙏','thanks please namaste'],['✌️','peace victory'],['💪','strong strength'],['👀','eyes look'],['🧠','brain idea'],['❤️','red heart love'],['💚','green heart'],['💙','blue heart'],['💜','purple heart'],['🤍','white heart'],['🖤','black heart'],['💔','broken heart'],['✨','sparkles magic'],['🔥','fire hot'],['💯','hundred perfect'],['✅','check success'],['❌','cross wrong'],['⚡','lightning fast'],['⭐','star favorite'],['🌟','glowing star'],['🎉','confetti celebration'],['🎯','target goal'],['🚀','rocket launch'],['💡','idea light'],['📷','camera photo'],['🎨','art design'],['💻','laptop code'],['📱','phone mobile'],['🎬','movie video'],['🎧','headphones music'],['📚','books study'],['📝','notes writing'],['🔒','lock secure'],['🔗','link'],['📌','pin important'],['🛠️','tools build'],['⚙️','settings gear'],['⏰','alarm clock'],['☕','coffee'],['🍕','pizza'],['🌱','plant grow'],['🌸','flower spring'],['🌈','rainbow'],['☀️','sun summer'],['🌙','moon night'],['🌍','world globe'],['🏔️','mountain nepal'],['🇳🇵','nepal flag'],['🇰🇷','korea flag'],['🇬🇧','uk english flag'],['🧋','bubble tea'],['🐱','cat'],['🐶','dog'],['🦋','butterfly'],['🐼','panda'],['🪄','magic wand']];
  mount.innerHTML=`<h2>Find a little expression</h2><label class="field"><span>Search emoji by name</span><input type="search" placeholder="Try love, fire, Nepal, or code…" data-emoji-search></label><p class="form-note">Tap an emoji to add it to your collection. Display depends on your device’s emoji font.</p><div class="emoji-grid"></div>`;let selected='';function preview(){result(out,{html:`<div class="emoji-output">${e(selected)||'✨'}</div>`,copy:selected||'✨',note:'Your selected emoji sequence. Unicode appearance varies between devices.'});}function render(q=''){const matches=emojis.filter(x=>x[1].includes(q.toLowerCase()));mount.querySelector('.emoji-grid').innerHTML=matches.length?matches.map(([s,label])=>`<button type="button" title="${e(label)}" aria-label="${e(label)}" data-emoji="${e(s)}">${s}</button>`).join(''):'<p class="form-note">No matching emoji. Try another word.</p>';mount.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{if(Array.from(selected).length>150){notify('Clear or copy your collection before adding more.');return;}selected+=b.dataset.emoji;preview();});}mount.querySelector('[data-emoji-search]').oninput=ev=>render(ev.target.value);render();preview();const clear=document.createElement('button');clear.className='btn secondary small';clear.textContent='Clear collection';clear.onclick=()=>{selected='';preview();};mount.append(clear);
 }
}
